-- IAM-R0 proposed reference catalog; OPT-IN and requires governance approval.
-- No COMMIT is issued. Review transaction and COMMIT manually in the SAME session.
SET DEFINE OFF;
SET SQLBLANKLINES ON;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;

-- REF_DOMAIN_TYPE
MERGE INTO IAM.REF_DOMAIN_TYPE t USING (SELECT 'WORKFORCE' c, 'کارکنان' fa, 'Workforce' en FROM dual) s ON (t.DOMAIN_TYPE_CODE=s.c)
WHEN NOT MATCHED THEN INSERT (DOMAIN_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,10,'Y','IAM_INIT',1);
