WHEN NOT MATCHED THEN INSERT (RESOURCE_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,10,'Y','IAM_INIT',1);
