WHEN NOT MATCHED THEN INSERT (RESOURCE_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,20,'Y','IAM_INIT',1);
MERGE INTO IAM.REF_RESOURCE_TYPE t USING (SELECT 'DATA_DOMAIN' c, 'دامنه داده' fa, 'Data Domain' en FROM dual) s ON (t.RESOURCE_TYPE_CODE=s.c)
WHEN NOT MATCHED THEN INSERT (RESOURCE_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,30,'Y','IAM_INIT',1);
MERGE INTO IAM.REF_RESOURCE_TYPE t USING (SELECT 'APPLICATION' c, 'سامانه' fa, 'Application' en FROM dual) s ON (t.RESOURCE_TYPE_CODE=s.c)
WHEN NOT MATCHED THEN INSERT (RESOURCE_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,40,'Y','IAM_INIT',1);
MERGE INTO IAM.REF_RESOURCE_TYPE t USING (SELECT 'REPORT' c, 'گزارش' fa, 'Report' en FROM dual) s ON (t.RESOURCE_TYPE_CODE=s.c)
WHEN NOT MATCHED THEN INSERT (RESOURCE_TYPE_CODE,NAME_FA,NAME_EN,SORT_ORDER,IS_ACTIVE,CREATED_BY,RECORD_VERSION) VALUES (s.c,s.fa,s.en,50,'Y','IAM_INIT',1);

PROMPT IAM_REFERENCE_SEED_PENDING_MANUAL_COMMIT;
